1	import "server-only";
2	import { createHash } from "node:crypto";
3	import { fetchWithHmac } from "./fetch-wrapper";
4	import { parseAuthenticatedUser, parseUserPublic } from "@lib/validation/user";
5	import { parsePagedEvents } from "@lib/validation/event";
6	import { getApiUrl, isApiUrlConfigured } from "@utils/api-helpers";
7	import type {
8	  AuthenticatedUserDTO,
9	  ProfileUpdateRequestDTO,
10	  ProfileUpdateResponseDTO,
11	  UserPublicResponseDTO,
12	} from "types/api/user";
13	import type {
14	  EventSummaryResponseDTO,
15	  PagedResponseDTO,
16	} from "types/api/event";
17	
18	// Strip control characters (incl. newlines, C1 controls, and the Unicode
19	// line/paragraph separators some log viewers and JS engines also treat as
20	// line terminators) before logging an upstream error body, so a
21	// malicious/broken backend response can't inject fake log lines into an
22	// aggregator that parses on line breaks. Truncated to the same 200-char
23	// bound `decodeSafeJwtClaims` below uses for logged summaries.
24	function sanitizeLoggedBody(body: string): string {
25	  return body.replace(/[\x00-\x1f\x7f-\x9f\u2028\u2029]/g, " ").slice(0, 200);
26	}
27	
28	/**
29	 * Authenticated session profile: GET /api/auth/me. Backend-owned fields
30	 * (avatarUrl/pictureSource/role/lastLoginAt) that the Logto id_token can't
31	 * carry — the id_token has no concept of an in-app avatar upload or login
32	 * audit trail.
33	 *
34	 * Throws with `.status` on non-OK so callers can distinguish:
35	 *   - 4xx (Bearer rejected — `profileEnrichmentFailed = "auth"`): the backend
36	 *     doesn't trust our access_token, so future Bearer calls will also 401
37	 *     until the wiring is fixed.
38	 *   - 5xx / network (transient): the session IS valid; we should keep the
39	 *     id_token-only user rather than visually-logging the user out.
40	 *   - 2xx: return the parsed AuthenticatedUserDTO, or null on Zod mismatch.
41	 *
42	 * Also decodes and logs the JWT payload (`iss`/`aud`/`exp`/`sub`) so a
43	 * future log capture reveals the audience/issuer mismatch that causes
44	 * the auth-rejection regression without redacting PII (email/name/picture
45	 * are stripped before logging).
46	 */
47	export async function getAuthenticatedUserExternal(
48	  accessToken: string
49	): Promise<AuthenticatedUserDTO | null> {
50	  if (!accessToken) return null;
51	  if (!isApiUrlConfigured()) return null;
52	  const apiUrl = getApiUrl();
53	
54	  // Decode the access_token payload (no signature verification — that's the
55	  // backend's job) and log iss/aud/exp/sub so a future ``getAuthenticatedUserExternal``
56	  // crash dump exposes the audience/issuer that the backend probably
57	  // doesn't trust. Email/name/picture claims are stripped before logging.
58	  const safeClaims = decodeSafeJwtClaims(accessToken);
59	
60	  try {
61	    const response = await fetchWithHmac(`${apiUrl}/auth/me`, {
62	      headers: { Authorization: `Bearer ${accessToken}` },
63	    });
64	    if (!response.ok) {
65	      const body = await response.text().catch(() => "<unreadable>");
66	      // 2026-07-26 round-10 (mirror of createEvent / uploadEventImage): surface
67	      // the WWW-Authenticate header so Spring's resource-server rejection
68	      // reason (RFC 6750) is one-grep root-caused across all entry points.
69	      // A bare `Bearer resource_metadata="..."` (no `error="..."` directive)
70	      // indicates Spring didn't even attempt JWT decode — same shape as the
71	      // shell-curl-with-no-Authorization response, which strongly suggests the
72	      // request never reached the resource-server's bearer-token filter.
73	      console.error(
74	        `getAuthenticatedUserExternal: HTTP ${response.status} \u2014 body=${body.slice(0, 200)} \u2014 www-authenticate=${response.headers.get("www-authenticate") ?? "<none>"} \u2014 access_token=${safeClaims}`,
75	      );
76	      const err = Object.assign(
77	        new Error(
78	          `getAuthenticatedUserExternal: HTTP ${response.status}`,
79	        ),
80	        { status: response.status },
81	      );
82	      throw err;
83	    }
84	    return parseAuthenticatedUser(await response.json());
85	  } catch (error) {
86	    if ((error as { status?: number })?.status) throw error;
87	    console.error(
88	      `getAuthenticatedUserExternal: failed (network/parse) \u2014 access_token=${safeClaims}`,
89	      error,
90	    );
91	    return null;
92	  }
93	}
94	
95	/**
96	 * Decode the JWT payload of an access_token without verifying the signature.
97	 * Returns a redacted summary suitable for inclusion in server logs:
98	 * `{iss, aud, exp, scope, sub}` — email/name/picture claims are stripped
99	 * because the production code has them elsewhere (AuthProvider) and a
100	 * redacted summary is enough to diagnose `aud`/`iss`/`exp`/`scope` mismatches.
101	 *
102	 * `scope` is included (capped at 200 chars) because Logto issues the
103	 * granted-permissions list as a space-separated string. Without it, the
104	 * 2026-07-26 silent "GET /api/auth/me works, POST /api/events 401" pattern
105	 * is indistinguishable between "wrong audience" and "missing resource
106	 * scope" — the two are different fixes (one is a JWKS/aud config, the other
107	 * is `LOGTO_API_SCOPES` not set). The string is not PII — it's the same
108	 * scope list the `scope=` query parameter carries in the OAuth flow.
109	 *
110	 * `sub` is the user's stable Logto subject identifier — unlike scope, it
111	 * IS a persistent, per-user value that could sit in log aggregators
112	 * indefinitely, so it's hashed rather than logged raw. The truncated hash
113	 * still lets an engineer correlate multiple log lines back to the same
114	 * session/user without exposing the actual identifier.
115	 */
116	export function decodeSafeJwtClaims(accessToken: string): string {
117	  try {
118	    const parts = accessToken.split(".");
119	    if (parts.length < 2) return "<unparseable-short-token>";
120	    const padded = parts[1]
121	      .replace(/-/g, "+")
122	      .replace(/_/g, "/")
123	      .padEnd(parts[1].length + ((4 - (parts[1].length % 4)) % 4), "=");
124	    const raw = Buffer.from(padded, "base64").toString("utf-8");
125	    const parsed = JSON.parse(raw) as Record<string, unknown>;
126	    // Logto's `scope` is a space-separated string per RFC 6749 §3.3. Cap to
127	    // 200 chars so a misconfigured tenant with thousands of scopes can't
128	    // bloat log lines; the cap is well above any plausible real scope set.
129	    const rawScope = typeof parsed.scope === "string" ? parsed.scope : undefined;
130	    const summary: Record<string, unknown> = {
131	      iss: parsed.iss,
132	      aud: parsed.aud,
133	      exp: parsed.exp,
134	      scope: rawScope ? rawScope.slice(0, 200) : undefined,
135	      sub:
136	        typeof parsed.sub === "string"
137	          ? createHash("sha256").update(parsed.sub).digest("hex").slice(0, 12)
138	          : undefined,
139	    };
140	    return JSON.stringify(summary);
141	  } catch {
142	    return "<unparseable-jwt>";
143	  }
144	}
145	
146	export async function getUserByUsernameExternal(
147	  username: string
148	): Promise<UserPublicResponseDTO | null> {
149	  if (!username || !username.trim()) return null;
150	  // Return null (no fetch) when the backend URL is genuinely unconfigured.
151	  // getApiUrl() falls back to a hardcoded default, so guarding on its result
152	  // is dead code and would fire a real request against the default host.
153	  if (!isApiUrlConfigured()) return null;
154	  const apiUrl = getApiUrl();
155	
156	  return fetchJsonWithFallback(
157	    `${apiUrl}/users/${encodeURIComponent(username)}`,
158	    parseUserPublic,
159	    null,
160	    "getUserByUsernameExternal",
161	  );
162	}
163	
164	/**
165	 * Shared shape for the "silent fallback" backend calls (public reads where a
166	 * 404/error should render as empty state, not surface as an error): fetch,
167	 * treat 404 as the fallback (the common, expected case, not an error), log +
168	 * fallback on any other non-OK or network failure, parse on success and fall
169	 * back if the payload doesn't validate.
170	 *
171	 * Anything other than 404 also falls back silently so callers render a clean
172	 * empty/not-found state instead of crashing, but a bare status number here
173	 * was indistinguishable from a genuine 404 in logs — a real "works locally,
174	 * 404s on staging" report (2026-07-30) took a manual server-log correlation
175	 * to rule out an auth/config failure masked as "doesn't exist" (it turned
176	 * out to be a genuinely missing row, but the log line gave no way to tell
177	 * without digging). Read the body and tag the log line so it's greppable as
178	 * a non-404 upstream failure going forward.
179	 */
180	async function fetchJsonWithFallback<T>(
181	  url: string,
182	  parse: (json: unknown) => T | null,
183	  fallback: T,
184	  label: string,
185	): Promise<T> {
186	  try {
187	    const response = await fetchWithHmac(url);
188	    if (response.status === 404) return fallback;
189	    if (!response.ok) {
190	      const body = await response.text().catch(() => "<unreadable>");
191	      console.error(
192	        `${label}: non-404 upstream failure HTTP ${response.status} — body=${sanitizeLoggedBody(body)}`
193	      );
194	      return fallback;
195	    }
196	    return parse(await response.json()) ?? fallback;
197	  } catch (error) {
198	    console.error(`${label}: failed`, error);
199	    return fallback;
200	  }
201	}
202	
203	/**
204	 * Patch the signed-in user's profile (username/displayName/bio).
205	 * Returns the updated ProfileUpdateResponseDTO — confirmed (2026-07-27)
206	 * against the real backend to be the same shape `GET /api/users/{username}`
207	 * returns, so it's parsed with `parseUserPublic`. It does NOT carry
208	 * `profileCompleted`/`role`/`lastLoginAt`; callers that need the fresh
209	 * `profileCompleted` must re-fetch `GET /api/auth/me` afterwards. Backend
210	 * returns 409 (taken) for collision, 400 for validation — we surface the
211	 * real status via re-throw so the route handler can map it correctly
212	 * without going through Zod parse.
213	 */
214	export async function patchMeProfileExternal(
215	  body: ProfileUpdateRequestDTO,
216	  accessToken: string,
217	): Promise<ProfileUpdateResponseDTO | null> {
218	  if (!accessToken || !isApiUrlConfigured()) return null;
219	  const apiUrl = getApiUrl();
220	
221	  try {
222	    const response = await fetchWithHmac(`${apiUrl}/users/me/profile`, {
223	      method: "PATCH",
224	      headers: {
225	        Accept: "application/json",
226	        "Content-Type": "application/json",
227	        Authorization: `Bearer ${accessToken}`,
228	      },
229	      body: JSON.stringify(body),
230	      skipBodySigning: true,
231	    });
232	    if (!response.ok) {
233	      const text = await response.text().catch(() => "");
234	      // Keep the real status so callers can distinguish 409 (taken) from
235	      // validation (400) and auth (403). The route handler maps to the
236	      // user-visible status without going through Zod parse.
237	      const err = Object.assign(
238	        new Error(
239	          `patchMeProfileExternal: HTTP ${response.status} — ${text.slice(0, 200)}`,
240	        ),
241	        { status: response.status },
242	      );
243	      throw err;
244	    }
245	    return parseUserPublic(await response.json());
246	  } catch (error) {
247	    if ((error as { status?: number })?.status) throw error;
248	    console.error("patchMeProfileExternal: failed", error);
249	    return null;
250	  }
251	}
252	
253	/**
254	 * Upload the signed-in user's avatar (multipart/form-data, field `avatarFile`).
255	 * Returns `{ avatarUrl }` per backend handoff. Mirrors `uploadEventImage`:
256	 * 2 MB cap held at the route; the wrapper forwards whatever File the caller
257	 * passes and lets fetchWithHmac HMAC-sign over an empty body for FormData.
258	 */
259	export async function uploadUserAvatarExternal(
260	  file: File,
261	  accessToken: string,
262	): Promise<{ avatarUrl: string } | null> {
263	  if (!file || !accessToken || !isApiUrlConfigured()) return null;
264	  const apiUrl = getApiUrl();
265	
266	  try {
267	    const formData = new FormData();
268	    formData.append("avatarFile", file);
269	    const response = await fetchWithHmac(`${apiUrl}/users/me/avatar`, {
270	      method: "POST",
271	      // fetch-wrapper ignores FormData bodies for signing (multipart bodies
272	      // can't be re-signed from a server-cloned stream). Backend uses HMAC
273	      // over the path+method only.
274	      headers: {
275	        Accept: "application/json",
276	        Authorization: `Bearer ${accessToken}`,
277	      },
278	      body: formData,
279	    });
280	    if (!response.ok) {
281	      const text = await response.text().catch(() => "");
282	      console.error(
283	        `uploadUserAvatarExternal: HTTP ${response.status} — ${text.slice(0, 200)}`,
284	      );
285	      const err = Object.assign(
286	        new Error(`uploadUserAvatarExternal: HTTP ${response.status}`),
287	        { status: response.status },
288	      );
289	      throw err;
290	    }
291	    const json: unknown = await response.json().catch(() => null);
292	    const avatarUrl =
293	      json && typeof json === "object" && typeof (json as { avatarUrl?: unknown }).avatarUrl === "string"
294	        ? (json as { avatarUrl: string }).avatarUrl
295	        : null;
296	    return avatarUrl ? { avatarUrl } : null;
297	  } catch (error) {
298	    if ((error as { status?: number })?.status) throw error;
299	    console.error("uploadUserAvatarExternal: failed", error);
300	    return null;
301	  }
302	}
303	
304	/** DELETE /api/users/me/avatar — clear the avatar.
305	 *  Throws with `.status` on non-ok so the route can map backend codes
306	 *  faithfully (a 401/403 stays 401/403 instead of being squashed to 502). */
307	export async function deleteUserAvatarExternal(
308	  accessToken: string,
309	): Promise<boolean> {
310	  if (!accessToken || !isApiUrlConfigured()) return false;
311	  const apiUrl = getApiUrl();
312	  try {
313	    const response = await fetchWithHmac(`${apiUrl}/users/me/avatar`, {
314	      method: "DELETE",
315	      headers: {
316	        Accept: "application/json",
317	        Authorization: `Bearer ${accessToken}`,
318	      },
319	      skipBodySigning: true,
320	    });
321	    if (!response.ok) {
322	      const text = await response.text().catch(() => "");
323	      const err = Object.assign(
324	        new Error(
325	          `deleteUserAvatarExternal: HTTP ${response.status} — ${text.slice(0, 200)}`,
326	        ),
327	        { status: response.status },
328	      );
329	      throw err;
330	    }
331	    return true;
332	  } catch (error) {
333	    if ((error as { status?: number })?.status) throw error;
334	    console.error("deleteUserAvatarExternal: failed", error);
335	    return false;
336	  }
337	}
338	
339	// Backend contract confirmed by Gerard 2026-07-30: the query param is
340	// `period` (required, lowercase `active` | `past`), not the `status` name
341	// this plan was drafted against. `active` includes upcoming + in-progress
342	// events. Kept as a domain-named `status` param at this function's boundary
343	// (see ProfileEventsSectionProps) so only this translation needed to change.
344	const PERIOD_BY_STATUS = { upcoming: "active", past: "past" } as const;
