347	 * Public listing of a user's events: GET /api/users/{username}/events.
348	 * Same paged shape as /events; the endpoint requires page, size, and
349	 * `period` (mapped from `status`) that scopes the profile's Propers /
350	 * Passats tabs.
351	 * Default size is 20 — matches the backend handoff and the
352	 * /[place] listing page size, so a public profile with many events
353	 * renders at the same density as the home page.
354	 * Returns an empty page on error so the profile renders "no events" rather
355	 * than crashing.
356	 */
357	export async function getUserEventsExternal(
358	  username: string,
359	  page = 0,
360	  size = 20,
361	  status: "upcoming" | "past" = "upcoming",
362	): Promise<PagedResponseDTO<EventSummaryResponseDTO>> {
363	  const empty: PagedResponseDTO<EventSummaryResponseDTO> = {
364	    content: [],
365	    currentPage: page,
366	    pageSize: size,
367	    totalElements: 0,
368	    totalPages: 0,
369	    last: true,
370	  };
371	  const trimmed = username?.trim();
372	  if (!trimmed) return empty;
373	  // Return an empty page (no fetch) when the backend URL is unconfigured —
374	  // getApiUrl() falls back to a default host, so guarding on it is dead code.
375	  if (!isApiUrlConfigured()) return empty;
376	  const apiUrl = getApiUrl();
377	
